    semiResult.total_runtime_microseconds =
        semiResult.preprocessing_runtime_microseconds +
        semiResult.solve_runtime_microseconds;

    semiResult.status = ResultStatus::OK;
    return semiResult;
}

#ifndef XCUT_SPARSIFIER_H_
#define XCUT_SPARSIFIER_H_

#include <ostream>
#include <unordered_set>
#include <vector>
#include <fmt/format.h>


#include "xcut/data_structures/graph.hpp"
#include "xcut/data_structures/graph_partition.hpp"

struct NodeInfo {
  NodeID m_id;
  EdgeWeight m_subtree_volume;
  EdgeWeight m_volume_below;
  EdgeWeight m_cut_below;

  NodeInfo() = default;
  NodeInfo(EdgeWeight subtree_volume);

  void reset();
};

std::ostream &operator<<(std::ostream &os, NodeInfo const &info);

namespace fmt {
template <> struct std::formatter<NodeInfo> : formatter<std::string> {
  // Format method required by {fmt} library. Use a template FormatContext
  // so it works with different format contexts (format_to, print, etc.).
  template <typename FormatContext>
  auto format(NodeInfo const &info, FormatContext &ctx) const
      -> decltype(ctx.out()) {
    return fmt::format_to(
        ctx.out(),
        "[ id = {}, subtree_volume = {}, below_volume = {}, below_cut = {} ]",
        info.m_id, info.m_subtree_volume, info.m_volume_below,
        info.m_cut_below);
  }
};
} // namespace fmt

struct ClusterInfo {

  NodeID m_num_clusters;
  std::vector<EdgeWeight> m_cluster_volumes;
  std::vector<EdgeWeight> m_cluster_below_volumes;
  std::vector<EdgeWeight> m_cluster_cut;

  /**
   * This vector stores the results of gains computations to save on the number
   * of recomputations needing to be done.
   */
  std::vector<std::vector<EdgeWeight>> m_gains;
  std::unordered_set<NodeID> m_moved;

  ClusterInfo(NodeID num_clusters);
};

class Sparsifier {
  using VertexWeights = std::vector<EdgeWeight>;
  using EdgeWeights = std::vector<EdgeWeight>;
  using Children = std::vector<NodeID>;

private:
  std::vector<const Graph *> m_graphs;
  std::vector<GraphPartition *> m_partitions;
  std::vector<std::vector<NodeInfo>> m_infos;

  // don't need the store the edge weights as the degree of a vertex in graph
  // m_graphs[i] gives the weight of the edge going to level i+1

public:
  Sparsifier() = default;

  ~Sparsifier();

  void push_back(Graph *g, GraphPartition *partition);

  NodeID size() const;

  EdgeWeight subtree_volume(NodeID level, NodeID u) const;

  NodeID id(NodeID level, NodeID u) const;

  bool same_subtree(NodeID u_level, NodeID u, NodeID v_level, NodeID v) const;

  bool same_subtree(NodeID level, NodeID u, NodeID v) const;

  EdgeWeight below_volume(NodeID level, NodeID u) const;

  EdgeWeight below_cut(NodeID level, NodeID u) const;

  /**
   * Weight of the edge going from level l upwards
   */
  EdgeWeight weight(NodeID level, NodeID u) const;

  bool finished() const;

  NodeID parent(NodeID level, NodeID u) const;

  auto child_range(NodeID level, NodeID u) {
    if (level == 0) {
      return GraphPart{};
    } else {
      return m_partitions[level - 1]->slice(u);
    }
  }

  std::vector<const Graph *> const &graphs() const;

  std::vector<GraphPartition *> const &partitions() const;

  std::vector<std::vector<NodeInfo>> const &infos() const;

  const Graph *graph(NodeID level);

  EdgeWeight graph_volume() const;

  void set_child_ids(NodeID level, NodeID u, NodeID id);

  void set_child_ids_if_match(NodeID level, NodeID u, NodeID id, NodeID old_id);

  void modify_parent_info_if_match(NodeID level, NodeID u,
                                   EdgeWeight volume_update,
                                   EdgeWeight cut_update, NodeID id);

  /**
   * Create a vector containing the cluster IDs. This should only be used at the
   * very end to get cluster information.
   */
  std::vector<NodeID> clustering(NodeID level) const;

  std::vector<NodeID> clustering();
};

/**
 * Answering connectivity queries using the sparsifier.
 */
bool connected(Sparsifier &sparsifier, NodeID u, NodeID v);

std::pair<NodeID, NodeID> normalized_cut(Sparsifier &sparsifier);

/**
 * Greedily compute a normalized cut.
 *
 * This function could probably be made faster, simplified and be parallelized
 * in a later version.
 */
std::vector<std::pair<NodeID, NodeID>> normalized_cut(Sparsifier &sparsifier,
                                                      NodeID k);

ClusterInfo compute_cluster_info(Sparsifier &sparsifier, NodeID level,
                                 NodeID num_clusters);

frac_t compute_normalized_cut(ClusterInfo const &cluster_info);

#endif

